  const add=(selector,vars,position)=>{const nodes=root.querySelectorAll(selector);if(nodes.length)tl.from(nodes,vars,position);};
  add('.greeting,.page-intro .eyebrow,.setup-intro .eyebrow',{y:10,autoAlpha:0},0);
  add('.headline-line>span,.page-intro h1,.setup-intro h1',{y:30,autoAlpha:0,stagger:.12},.07);
