function profileError(p){if(!PERSONA_IDS.includes(p.persona))return t('先选一只 Kora。','Choose your Kora first.');if(!p.name.trim()||p.name.length>20)return t('请输入1—20个字的昵称。','Enter a name of 1–20 characters.');if(p.height!==''&&(!Number.isFinite(Number(p.height))||Number(p.height)<80||Number(p.height)>250))return t('请确认身高，填写80—250之间的数值（cm）。','Check your height: enter a number from 80 to 250 cm.');if(p.weight!==''&&(!Number.isFinite(Number(p.weight))||Number(p.weight)<20||Number(p.weight)>400))return t('请确认体重，填写20—400之间的数值（kg）。','Check your weight: enter a number from 20 to 400 kg.');if(!p.activities.length)return t('至少选一种你想尝试的运动。','Choose at least one kind of movement.');return '';}

