function planTitle(p=state.plan){if(p.type==='rest')return t('今天休息','Rest day');if(p.type==='reschedule')return t(`${p.minutes} 分钟训练 · 已改期`,`${p.minutes}-minute session · rescheduled`);const action=p.action||({light:'cardio',strength:'strength',stretch:'stretch',walk:'walk'}[p.workout])||'cardio';return t(`${p.minutes} 分钟${activityLabel(action)}`,`${p.minutes} min ${activityLabel(action).toLowerCase()}`);}
function planWhen(p=state.plan){return `${p.type==='reschedule'?displayDate(p.targetDate||calendar.addDays(state.date,1)):t('今天','Today')} · ${p.minutes?t(p.minutes+' 分钟',p.minutes+' min'):t('休息','Rest')}`;}
function reminderText(){return pair(lifestyle.timeLabels[state.profile.preferredTime]||lifestyle.timeLabels.flexible)+t(' · 仅记录偏好，未开启通知',' · preference saved; notifications off');}
