function dayStatus(day){if(!day)return t('未记录','No record');if(day.plan?.done)return t('已完成','Done');if(day.plan?.type==='rest')return t('休息','Rest');if(day.plan?.type==='reschedule')return t('已改期','Moved');if(day.plan)return day.plan.minutes+t('分钟',' min');return day.logs.length?t('有餐食','Meal logged'):t('未安排','Open');}
function weekStrip(){const labels=t(['一','二','三','四','五','六','日'],['M','T','W','T','F','S','S']);const dates=calendar.weekDates(calendar.addDays(state.date,weekOffset*7));return `<div class="week-controls"><button data-week="-1" aria-label="${t('查看上一周','Previous week')}">← ${t('上周','Prev')}</button><span>${dates[0]} — ${dates[6]}</span><button data-week="1" aria-label="${t('查看下一周','Next week')}">${t('下周','Next')} →</button></div>${weekOffset?`<button class="text-link" data-action="this-week">${t('回到本周','This week')}</button>`:''}<div class="week-strip">${dates.map((key,i)=>{const day=state.days[key],status=dayStatus(day);return `<button class="day ${key===state.date?'today':''} ${day?.plan?.done?'done':''} ${day?.plan?'scheduled':''}" data-history-date="${key}" aria-label="${displayDate(key)} · ${status}" ${key===state.date?'aria-current="date"':''}><small>${labels[i]}</small><b>${calendar.parseDate(key).getDate()}</b><span class="day-dot"></span><small class="day-status">${status}</small></button>`;}).join('')}</div>`;}
function historySummary(){const keys=Object.keys(state.days).filter(k=>k<state.date).sort().reverse().slice(0,7);return `<div class="memory-note"><p>${t('过去的记录，留在它发生的那一天。','Every day keeps its own story.')}</p>${keys.length?keys.map(k=>`<button data-history-date="${k}">${displayDate(k)} · ${dayStatus(state.days[k])} ↗</button>`).join(''):`<small>${t('从今天开始积累，点击周历查看每日记录。','Start today. Select a date to see its records.')}</small>`}${state.legacy?`<button data-action="legacy">${t('查看旧版无日期记录','View undated earlier records')} ↗</button>`:''}</div>`;}
function historyMeals(logs){return logs.length?logs.map(l=>`<p>${escapeHTML(foodName(l))} · ${escapeHTML(l.grams)} g · ${escapeHTML(l.cal)} kcal</p>`).join(''):`<p>${t('没有餐食记录。','No meal entries.')}</p>`;}
function showHistory(key){if(!/^\d{4}-\d{2}-\d{2}$/.test(key))return;const day=state.days[key];openModal(modalShell(`<h2 id="modal-title">${displayDate(key)}</h2><p class="modal-sub">${dayStatus(day)}</p>${day?.plan?`<p>${planTitle(day.plan)}</p>`:''}${day?.comeback?`<p>${t('当天状态：','Energy: ')}${pair(energyData[day.comeback.energy]?.title||['已记录','Recorded'])} · ${day.comeback.done?t('已照顾自己','Care recorded'):t('已确认安排','Arrangement confirmed')}</p>`:''}${day?.restCheckin?`<p>${t('休息日回顾：','Rest-day check-in: ')}${pair({tired:['有点累，想缓一缓','Tired, taking it easy'],okay:['休息之后好多了','Better after a rest'],sore:['身体不舒服，需要休息','Uncomfortable, I need rest']}[day.restCheckin.mood]||['已记录','Recorded'])}</p>`:''}${day?historyMeals(day.logs):''}${key>state.date&&day?.plan?.source==='report'&&!day.plan.done?`<button class="text-link" data-action="cancel-reservation" data-date="${key}">${t('取消这一天的预约','Cancel this reservation')}</button>`:''}<button class="primary" data-action="close">${t('知道了','Done')}</button>`,t('每日记录','Daily records')),'history:'+key);}
function showLegacy(){const old=state.legacy;if(!old)return;openModal(modalShell(`<h2 id="modal-title">${t('旧版无日期记录','Earlier undated records')}</h2><p class="modal-sub">${t('这些旧记录没有可靠日期，单独保留，不计入今天。','These older records have no reliable date. They are kept separately from today.')}</p><p>${old.plan?planTitle(old.plan):''}</p>${historyMeals(old.logs||[])}<button class="primary" data-action="close">${t('知道了','Done')}</button>`,t('旧版记录','Earlier records')),'legacy');}
