let pathWeekOffset=0,lastFocusedPathDate=null;
function focusTodayNode(){if(pathWeekOffset){pathWeekOffset=0;render();}document.querySelector('[data-action="today-plan"]')?.scrollIntoView({block:'center',behavior:'instant'});}
function weekStatus(row){if(row.today)return nodeStatus();const labels={done:['训练已完成','Workout completed'],rest:['休息日','Rest day'],moved:['已改期','Rescheduled'],planned:['已有安排','Planned'],recorded:['有记录','Recorded'],empty:['未记录','No record'],future:['待安排','Not planned yet']};return pair(labels[row.kind]);}
function weekCoach(){return `<div class="week-coach"><button class="kora-live coach-touch" data-kora-live="${state.profile.persona}" data-action="coach-interact" aria-label="${t('点点 Kora，听它说句话','Tap Kora for a little encouragement')}">${portrait(state.profile.persona,'companion-source')}<canvas aria-hidden="true"></canvas></button><div class="coach-bubble" role="status" aria-live="polite" aria-atomic="true" hidden></div></div>`;}
function interactCoach(){
 const stage=document.querySelector('.coach-touch'),bubble=document.querySelector('.coach-bubble');if(!stage||!bubble||Date.now()-lastCoachTap<3000)return;
 lastCoachTap=Date.now();const mode=coach.context(state.plan),key=state.profile.persona+':'+mode,response=coach.pick(state.profile.persona,mode,coachLastLines[key]);coachLastLines[key]=response.index;
 bubble.textContent=pair(response.line);bubble.hidden=false;clearTimeout(coachTimer);coachTimer=setTimeout(()=>{bubble.hidden=true;},4200);
 if(state.profile.motionPaused||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 stage.dispatchEvent(new CustomEvent('kora-greet'));coachTween?.kill();
 if(window.gsap){const poses=[{y:-7,rotation:0},{y:-2,rotation:-5},{y:-4,rotation:4}],pose=poses[response.gesture];coachTween=gsap.timeline().to(stage,{...pose,duration:.2,ease:'power2.out'}).to(stage,{y:0,rotation:0,duration:.48,ease:'back.out(1.5)',clearProps:'transform'});}
}
