function journeySection(){
 const rows=journey.weekNodes(state,pathWeekOffset),scene=currentScene(),future=pathWeekOffset===1,points=rows.map((row,i)=>({x:[250,294,300,250,200,206,250][i],y:155+i*185}));
 // Shared tangents keep a continuous, gentle bend through the seven node centers.
 const d=points.reduce((path,p,i)=>{if(!i)return `M${p.x} ${p.y}`;const a=points[i-1],before=points[Math.max(0,i-2)],after=points[Math.min(points.length-1,i+1)];return path+` C${a.x+(p.x-before.x)/6} ${a.y+(p.y-before.y)/6} ${p.x-(after.x-a.x)/6} ${p.y-(after.y-a.y)/6} ${p.x} ${p.y}`;},'');
 return `<section class="path-home weekly-home scene-${scene}" aria-labelledby="home-title">${landscape(scene)}<div class="path-top week-toolbar"><div><p class="eyebrow">${future?t('下周预告','NEXT WEEK'):t('这一周，慢慢走','ONE WEEK AT A TIME')}</p><h1 id="home-title">${pair(sceneNames[scene])}</h1><p class="week-range">${rows[0].date} — ${rows[6].date}</p></div><div class="week-tools"><button class="records-link" data-action="record-hub">${t('我的记录','My records')}</button><button class="text-link" data-action="focus-today">${t('回到今天','Back to today')} ↓</button></div></div>${future?`<div class="next-week-intro"><h2>${t('下一段路，下周再走。','Next week can wait.')}</h2><p>${t('先按自己的节奏过好这一周。已确认的下周安排，可以点开查看。','Take this week at your own pace. You can still view any plans you have already saved for next week.')}</p></div>`:''}<div class="path-stage trail-map week-stage"><svg class="week-ribbon" viewBox="0 0 560 1390" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" fill="none" stroke="#e1e7d7" stroke-width="20" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#fcfdf8" stroke-width="2" stroke-dasharray="2 10" stroke-linecap="round"/></svg>${rows.map((row,i)=>{const glyph=row.today?(row.kind==='rest'?'moon':row.kind==='moved'?'clock':row.kind==='done'?'check':'arrow'):null;return `<div class="week-stop ${row.today?'is-today':''} kind-${row.kind}" style="left:${points[i].x/560*100}%;top:${points[i].y}px" data-week-node="${row.date}">${row.today?`<div class="week-node-label"><small>${displayDate(row.date)}</small></div>`:''}<button class="trail-node ${row.today?'today-node':''} ${row.kind==='done'?'is-past':''}" ${row.today?'data-action="today-plan" aria-current="date"':`data-week-date="${row.date}"`} aria-label="${row.today?t('查看今日安排','Open today’s plan'):displayDate(row.date)} · ${weekStatus(row)}" aria-haspopup="dialog">${glyph?icon(glyph):`<span>${Number(row.date.slice(-2))}</span>`}</button>${row.today?weekCoach():''}${row.today&&state.wallet?.bird?'<img class="trail-bird" src="assets/kora-shop-bird.svg" alt="">':''}</div>`;}).join('')}</div><div class="week-end">${future?`<button class="secondary" data-action="focus-today">← ${t('回到今天','Back to today')}</button>`:`<p>${t('一周七天，不必每天训练。','Seven days. Not seven required workouts.')}</p><button class="next-week-button" data-action="next-path-week"><span>${t('下一周','Next week')} ${icon('arrow')}</span><small>${t('看看下一段路','A peek at the next chapter')}</small></button>`}</div>${shopDock()}</section>`;
}
function showWeekDay(date){const rows=journey.weekNodes(state,pathWeekOffset),row=rows.find(r=>r.date===date);if(!row)return;if(row.today){showTodayPlan();return;}if(date<=state.date){showHistory(date);return;}openModal(modalShell(`<h2 id="modal-title">${displayDate(date)}</h2><p class="modal-sub">${row.plan?planTitle(row.plan):t('这一天还没安排。','Nothing planned for this day yet.')}</p><p>${pathWeekOffset?t('先过好这一周，下周到了再一起出发。已有安排会保留，不需要提前打卡。','Let’s take care of this week first. Saved plans stay here; there is no need to check in early.'):t('到了这一天，再按当时的状态开始。现在不用提前完成。','When the day comes, start with how you feel then. There is nothing to complete early.')}</p>${row.plan?.targetDate?`<p>${t('改期至：','Moved to: ')}${displayDate(row.plan.targetDate)}</p>`:''}<button class="primary" data-action="focus-today">${t('回到今天','Back to today')}</button>`,t('安排预览','PLAN PREVIEW')),'week-day:'+date);}
function today(){return journeySection();}
function showTodayPlan(){const p=state.plan,rest=p.type==='rest',moved=p.type==='reschedule',normal=!rest&&!moved,done=p.done||todayCare()?.done;
 const main=normal&&!done?`<button class="primary" data-action="${p.session?'show-session':'start-session'}">${p.session?t('回到训练','Back to my session'):t('开始今天的训练','Start today’s session')}${icon('arrow')}</button>`:rest?`<button class="primary" data-action="comeback-energy">${t('想活动了？重新安排','Ready to move? Make a plan')}</button>`:moved?`<button class="primary" data-action="resume-plan">${t('今天也想动一动','Plan something for today')}</button>`:`<p class="routine-done">${icon('check')}${t('今天的行动，已经记下了。','Today’s effort is recorded.')}</p>`;
 openModal(modalShell(`<div class="plan-panel-head"><div><p class="eyebrow">${displayDate(state.date)}</p><h2 id="modal-title">${nodeStatus()}</h2></div>${portrait()}</div><div class="plan-panel-task"><small>${t('今日安排','TODAY’S PLAN')}</small><h3>${planTitle()}</h3><p>${moved?displayDate(p.targetDate):reminderText()}</p>${p.session&&!done&&normal?`<p><span data-session-clock>${sessionTime()}</span> · ${p.session.running?t('计时中','Timer running'):t('已暂停','Paused')}</p>`:''}</div><p class="plan-panel-speech">${routineSpeech()}</p><div class="plan-panel-actions">${main}${rest?`<button class="secondary" data-action="rest-checkin">${state.days[state.date].restCheckin?t('查看今日回顾','View my check-in'):t('记一下今天的状态 · +1 叶子','A little check-in · +1 leaf')}</button>`:''}${normal&&!done?`<button class="secondary" data-action="adjust-reason">${t('今天想调整一下','I’d like to adjust today')}</button>`:''}</div><div class="plan-panel-links">${normal?`<button class="text-link" data-action="training-done">${done?t('标错了？更正记录','Correct this record'):t('我已经完成了','I’ve already finished')}</button>`:''}${!done&&normal&&lifestyle.valid(state.profile.lifestyle)?`<button class="text-link" data-life="plan">${t('按最新偏好重新安排','Review my latest preferences')}</button>`:''}${state.undo?`<button class="text-link" data-action="undo">${t('撤销上次调整','Undo last change')}</button>`:''}<button class="text-link" data-action="go-chat">${t('和 Kora 聊聊','Talk to Kora')} ↗</button></div>`,t('今日安排','TODAY’S PLAN')),'today-plan');}
function showAdjustReason(){openModal(modalShell(`<h2 id="modal-title">${t('今天是什么情况？','What’s today like?')}</h2><p class="modal-sub">${t('选最接近的就好，也可以跳过。先聊清楚，再决定怎么改。','Choose what fits, or skip this. We’ll review any changes together.')}</p><div class="adjust-reasons">${[['time',['时间不够，临时有事','Short on time or plans changed']],['tired',['没什么精神，想歇歇','Low on energy']],['return',['今天就是不太想练','Just not feeling it']]].map(([id,label])=>`<button class="option" data-issue="${id}">${icon(issueIcons[id])}<span>${pair(label)}</span></button>`).join('')}<button class="option" data-action="not-well">${icon('heart')}<span>${t('身体不舒服','I’m not feeling well')}</span></button></div><div class="modal-actions"><button class="text-link" data-action="today-plan">${t('返回今日安排','Back to today’s plan')}</button><button class="text-link" data-issue="adjust">${t('跳过，直接选安排','Skip to options')}</button></div>`,t('先听听你','LET’S CHECK IN')),'adjust-reason');}
function showNotWell(){openModal(modalShell(`<h2 id="modal-title">${t('先照顾身体。','Take care of yourself first.')}</h2><p class="modal-sub">${t('不舒服就先停下来，不用硬撑。这里不能判断你的身体状况。','Stop if you feel unwell; you don’t need to push through. This preview cannot assess your condition.')}</p>${state.plan.session?`<p class="helper">${t('训练计时已暂停。','Your session timer is paused.')}</p>`:''}<p>${t('可以先把今天改为休息，或者去聊聊。确认后才会修改计划。','You can choose a rest day or talk to Kora. Your plan changes only after confirmation.')}</p><div class="modal-actions"><button class="secondary" data-action="go-chat">${t('先聊聊','Let’s talk')}</button><button class="primary" data-energy="rest">${t('看看休息安排','Review a rest day')}</button></div>`,t('身体优先','CARE FIRST')),'not-well');}
function showRecordHub(){openModal(modalShell(`<h2 id="modal-title">${t('我的记录','My records')}</h2><p class="modal-sub">${t('走过的路，都在这里。','Your steps are here to look back on.')}</p><div class="record-hub"><button class="option" data-action="records">${icon('clock')}<span><strong>${t('按日期查看','Browse by date')}</strong><small>${t('训练、休息和餐食记录','Workouts, rest and meals')}</small></span></button><button class="option" data-action="open-report">${icon('leaf')}<span><strong>${t('这一周的来信','Your weekly note')}</strong><small>${t('看看这一周，再安排下一周','Reflect and plan your next week')}</small></span></button><button class="option" data-action="open-month">${icon('moon')}<span><strong>${t('月度回顾','Monthly reflection')}</strong><small>${t('把时间拉长一点看','Look at the bigger picture')}</small></span></button></div>${state.legacy?`<button class="text-link" data-action="legacy">${t('旧版无日期记录','Earlier undated records')}</button>`:''}`,t('一起走过','OUR JOURNEY')),'record-hub');}
function showRecords(){openModal(modalShell(`<h2 id="modal-title">${t('按日期翻翻记录','Browse your records')}</h2>${weekStrip()}<p class="helper">${t('未记录不代表没有行动；未来的安排不会计入完成。','No record does not mean no activity. Future plans do not count as completed.')}</p>`,t('记录明细','RECORD DETAILS')),'records');}
const rewardNames={trail:['树荫小径','The shady trail'],bird:['枝头小鸟','A little bird'],creek:['溪边营地','Creekside camp'],stars:['星光林地','Starlight grove']};
const rewardDescriptions={trail:['熟悉的小路，随时欢迎你回来。','A familiar trail, always here for you.'],bird:['一位安静的新邻居，偶尔歪头看看你。','A quiet neighbour with a curious little head tilt.'],creek:['沿着溪水走，去树下的小帐篷歇一歇。','Follow the stream to a cosy woodland tent.'],stars:['月光照着小路，慢慢走也有星星陪你。','A moonlit trail with a few stars for company.']};
let shopTab='browse',shopPreview=null,leafGain=0;
function shopDock(){return `<button class="leaf-shop-dock" data-action="leaf-shop" aria-label="${t('打开树叶商店','Open the Leaf Shop')}"><span class="shop-house" aria-hidden="true"><svg viewBox="0 0 64 54"><path d="M12 24h40v24H12Z" fill="#e5d6b8"/><path d="m5 26 27-22 27 22Z" fill="#83996d"/><path d="M26 33h12v15H26Z" fill="#9b8869"/><path d="M16 29h8v8h-8Z" fill="#fff6d8"/><path d="M42 29h6v8h-6Z" fill="#fff6d8"/><path d="M8 49h48" stroke="#a5b48f" stroke-width="3" stroke-linecap="round"/></svg></span><span>${t('树叶商店','Leaf Shop')}<strong>${icon('leaf')} ${Math.max(0,rewards.balance(state))}</strong></span></button>`;}
function rewardPreview(id){const scene={trail:0,creek:1,stars:2}[id];return id==='bird'?`<div class="reward-preview bird-preview"><img src="assets/kora-shop-bird.svg" alt=""></div>`:`<div class="reward-preview scene-${scene}">${landscape(scene)}<svg class="preview-path" viewBox="0 0 320 180" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><path d="M130 190C40 130 235 90 150-10" stroke="#d9e2cb" stroke-width="18" fill="none"/><path d="M130 190C40 130 235 90 150-10" stroke="#fcfdf5" stroke-width="2" stroke-dasharray="1 7" stroke-linecap="round" fill="none"/><circle cx="166" cy="92" r="11" fill="#f7faee" stroke="#99af80" stroke-width="3"/></svg></div>`;}

function showRewards(){
 const balance=rewards.balance(state),owned=id=>rewards.owns(state,id),names={browse:['逛商店','Shop'],collection:['我的收藏','Collection'],ledger:['积分明细','Leaf history']};
 const rules=`<details class="leaf-rules"><summary>${t('叶子怎么获得？','How do I earn leaves?')}</summary><p>${t('每天：完成训练或休息日状态回顾 +1，保存第一条饮食记录 +1，最多 2 片。短训练同样算，吃什么不影响奖励。','Each day: finish a session OR a rest-day check-in for +1, and save your first meal for +1. Up to 2 leaves a day. Short sessions count; food choices never affect rewards.')}</p><p>${t('叶子不过期，不因缺席扣分。补记不重复奖励。误记撤销会校正积分；已兑换物品保留，余额不足部分由之后获得的叶子补齐。','Leaves never expire and breaks cost nothing. Backdated entries do not earn extra leaves. Corrections adjust your balance; redeemed items stay yours, and future leaves cover any shortfall.')}</p><p>${t('旧记录已一次性折算，旧版已解锁的背景免费保留。数据保存在当前浏览器。','Earlier records are credited once, and previously unlocked scenes stay yours for free. Saved in this browser.')}</p></details>`;
 let body;
 if(shopPreview){const item=rewards.items.find(i=>i.id===shopPreview);body=`<button class="text-link" data-shop-back>← ${t('返回商店','Back to shop')}</button>${rewardPreview(item.id)}<h3>${pair(rewardNames[item.id])}</h3><p>${pair(rewardDescriptions[item.id])}</p><p>${balance>=item.price?t('兑换后剩余','Balance after exchange')+': '+(balance-item.price)+' 🍃':t(`还差 ${item.price-balance} 片叶子`,`Collect ${item.price-balance} more leaves`)}</p><button class="primary" data-buy="${item.id}" ${balance<item.price||owned(item.id)?'disabled':''}>${t('确认兑换','Confirm exchange')} · ${item.price} 🍃</button>`;}
 else if(shopTab==='ledger'){body=`<div class="leaf-ledger">${[...(state.wallet?.ledger||[])].reverse().map(e=>`<div><span><strong>${e.kind==='experience'?t('体验赠送','Preview gift'):e.kind==='purchase'?t('兑换 · ','Exchanged · ')+pair(rewardNames[e.item]):e.reason==='correction'?t('更正记录','Record correction'):e.reason==='migration'?t('旧记录折算','Earlier records'):e.kind==='food'?t('记录饮食','Meal recorded'):t('照顾自己','Daily care')}</strong><small>${escapeHTML(e.sourceDate||e.date)}</small></span><b>${e.delta>0?'+':''}${e.delta} 🍃</b></div>`).join('')||`<p>${t('第一片叶子，从今天的小行动开始。','Your first leaf starts with a small step today.')}</p>`}</div>`;}
 else body=`<div class="shop-grid">${rewards.items.filter(i=>shopTab!=='collection'||owned(i.id)).map(i=>`<article>${rewardPreview(i.id)}<h3>${pair(rewardNames[i.id])}</h3><p>${pair(rewardDescriptions[i.id])}</p>${owned(i.id)?i.id==='bird'?`<button class="secondary" data-toggle-bird aria-pressed="${Boolean(state.wallet?.bird)}">${state.wallet?.bird?t('收起小鸟','Put bird away'):t('请小鸟来作伴','Invite the bird')}</button>`:`<button class="secondary" data-scene="${i.scene}" aria-pressed="${currentScene()===i.scene}">${currentScene()===i.scene?t('正在使用','In use'):t('使用背景','Use scene')}</button>`:`<button class="secondary" data-preview-reward="${i.id}">${t('预览','Preview')} · ${i.price} 🍃</button><small>${balance<i.price?t(`还差 ${i.price-balance} 片叶子`,`Collect ${i.price-balance} more leaves`):t('可以兑换啦','Ready to exchange')}</small>`}</article>`).join('')}</div>`;
 openModal(modalShell(`<div class="shop-heading"><div><p class="eyebrow">${t('把日常变成小风景','LITTLE MOMENTS, LOVELY PLACES')}</p><h2 id="modal-title">${t('树叶商店','The Leaf Shop')}</h2></div><div class="leaf-balance">${icon('leaf')}<strong>${Math.max(0,balance)}</strong><small>${t('片叶子','leaves')}</small></div></div>${balance<0?`<p class="leaf-adjustment">${t(`更正记录后，还有 ${-balance} 片待补回。已兑换的风景仍然属于你。`,`After a record correction, ${-balance} leaves remain to cover. Your collected rewards stay yours.`)}</p>`:''}<div class="shop-tabs" role="group" aria-label="${t('商店栏目','Shop sections')}">${Object.entries(names).map(([key,label])=>`<button data-shop-tab="${key}" aria-pressed="${shopTab===key&&!shopPreview}">${pair(label)}</button>`).join('')}</div>${body}${rules}`,t('一点点照顾，一片片收集','A LITTLE CARE, A LEAF AT A TIME')),'rewards');
}
function showRestCheckin(){const check=state.days[state.date].restCheckin;openModal(modalShell(`<h2 id="modal-title">${t('今天，身体感觉怎么样？','How are you feeling today?')}</h2><p>${t('休息也是照顾自己。选一个最接近现在的感受，就够了。','Rest is care, too. Just choose what feels closest right now.')}</p><form id="rest-checkin-form"><label for="rest-mood">${t('现在的状态','How I feel')}</label><select id="rest-mood" required><option value="">${t('选一个感受','Choose a feeling')}</option>${[['tired',['有点累，想缓一缓','Tired, taking it easy']],['okay',['休息之后好多了','Better after a rest']],['sore',['身体不舒服，需要休息','Uncomfortable, I need rest']]].map(([id,label])=>`<option value="${id}" ${check?.mood===id?'selected':''}>${pair(label)}</option>`).join('')}</select><button class="primary" type="submit">${t('记下今天的状态','Save my check-in')}</button></form>${check?`<button class="text-link" data-action="undo-rest-checkin">${t('标错了，撤销这条回顾','Undo this check-in')}</button>`:''}`,t('休息日回顾','REST-DAY CHECK-IN')),'rest-checkin');}

function reportInsight(r){if(!r.recordedDays)return t('这里暂时没有记录。等你留下一次行动，我们再一起回顾。','No records in this period yet. We can reflect after your first recorded action.');if(!r.completed)return t('这一段时间，你留下了休息、饮食或调整的记录。训练暂未标记完成，我们不替你下结论。','You recorded food, rest or changes. No workout is marked complete; that alone does not tell us what you did.');if(r.shortDone)return t(`你确认完成了 ${r.completed} 次训练，其中 ${r.shortDone} 次是缩短后的安排。调整过，也一样算数。`,`You confirmed ${r.completed} ${r.completed===1?'session':'sessions'}, including ${r.shortDone} shortened ${r.shortDone===1?'plan':'plans'}. Adjusting still counts.`);return t(`你确认完成了 ${r.completed} 次训练。这些脚印都在，下一步按你的实际状态来。`,`You confirmed ${r.completed} ${r.completed===1?'session':'sessions'}. Those steps stay with you. Let your next step fit your day.`);}
function showReport(){const r=journey.report(state,reportKind,reportOffset),unit=reportKind==='week'?t('周','week'):t('月','month');openModal(modalShell(`<div class="report-switch"><button data-report-kind="week" aria-pressed="${reportKind==='week'}">${t('周报','Weekly')}</button><button data-report-kind="month" aria-pressed="${reportKind==='month'}">${t('月报','Monthly')}</button></div><h2 id="modal-title">${t((reportKind==='week'?'这一周':'这个月')+'，我们走过。','Your '+unit+', with Kora.')}</h2><div class="report-period"><button class="text-link" data-report-offset="-1" aria-label="${t('上一'+unit,'Previous '+unit)}">←</button><span>${r.start} — ${r.end}${r.partial?`<small>${t('进行中 · 截至今天','In progress · through today')}</small>`:''}</span><button class="text-link" data-report-offset="1" aria-label="${t('下一'+unit,'Next '+unit)}" ${reportOffset===0?'disabled':''}>→</button></div><div class="report-letter"><img src="assets/kora-cheer-wink-v4.png" alt="Kora"><p>${reportInsight(r)}</p></div><div class="report-stats"><div><b>${r.completed}</b><span>${t('确认完成训练','Sessions confirmed')}</span></div><div><b>${r.rest}</b><span>${t('安排休息天数','Rest days planned')}</span></div><div><b>${r.mealDays}</b><span>${t('饮食记录天数','Days with food logs')}</span></div><div><b>${r.adjustedDays}</b><span>${t('调整安排天数','Days with plan changes')}</span></div></div><section class="report-detail"><h3>${t('运动与时间','Movement & time')}</h3>${Object.entries(r.types).length?Object.entries(r.types).map(([id,count])=>`<div class="report-bar"><span>${activityLabel(id)}</span><meter min="0" max="${r.completed}" value="${count}">${count}</meter><b>${count}</b></div>`).join(''):`<p>${t('还没有确认完成的训练。','No confirmed sessions yet.')}</p>`}<p>${t('完成训练中的计时记录：','Timer records from completed sessions: ')}<strong>${r.timedCount?`${Math.floor(r.timedMs/60000)} ${t('分','min')} ${Math.floor(r.timedMs/1000)%60} ${t('秒','sec')}`:t('尚无计时记录','No timed sessions')}</strong></p><small>${t(`${r.timedCount} 次有计时，${r.untimedCount} 次未记录时长。计时不等于实际运动量；未用计划时长补齐。`,`${r.timedCount} timed; ${r.untimedCount} without time records. Timer data is not verified activity; planned minutes are never substituted.`)}</small></section><section class="report-next"><h3>${t('给下周留一点余地。','Make a little room for next week.')}</h3><p>${r.completed>=2&&r.shortDone>=Math.ceil(r.completed/2)?t('这段时间，至少一半完成的训练采用了缩短安排。下周可以考虑从 10 分钟开始，具体由你决定。','At least half of your completed sessions used shortened plans. Consider a 10-minute starting point next week; you decide.'):t('记录还不足以判断哪种安排最适合你。先沿用档案偏好，你也可以自行调整。','These records cannot establish your ideal routine. We can start with your profile preferences, and you can adjust.')}</p><button class="primary" data-action="schedule-review">${t('看看下周建议','Review next week')} ${icon('arrow')}</button></section><details class="report-records"><summary>${t('查看统计依据','See the records behind this')}</summary><p>${t('当前每天最多统计一条确认完成的训练计划；休息、饮食和改期不算训练。未记录不等于没运动。','Currently counts at most one confirmed workout plan per day. Rest, food and rescheduling are separate. Missing records do not mean no activity.')}</p>${r.done.map(e=>`<button class="text-link" data-history-date="${e.date}">${displayDate(e.date)} · ${planTitle(e.plan)} ↗</button>`).join('')}</details><p class="helper">${t('基于此浏览器记录生成，不自动发送。','Generated from this browser’s records. Not sent automatically.')}</p>`,t('KORA 来信','A NOTE FROM KORA')),'report');}
function showSchedule(){const r=journey.report(state,reportKind,reportOffset),days=calendar.weekDates(calendar.addDays(state.date,7));scheduleForm||={dates:[days[0],days[3]],minutes:journey.suggestedMinutes(state,r),activity:calendar.defaultPlan(state).action};openModal(modalShell(`<h2 id="modal-title">${t('下周，先这样安排？','A starting plan for next week?')}</h2><p class="modal-sub">${t('这是可修改的安排草稿，不是训练处方。只添加空闲日期，已有安排保留。','An editable planning draft, not an exercise prescription. Only open dates are added; existing plans stay.')}</p><fieldset class="schedule-days"><legend>${t('选择你想运动的日子','Choose your days')}</legend>${days.map(date=>`<label><input type="checkbox" data-schedule-date="${date}" ${scheduleForm.dates.includes(date)?'checked':''} ${state.days[date]?.plan?'disabled':''}><span>${displayDate(date)}${state.days[date]?.plan?` · ${t('已有安排','Already planned')}`:''}</span></label>`).join('')}</fieldset><div class="form-grid"><div class="field"><label for="schedule-minutes">${t('每次计划时长','Planned duration')}</label><select id="schedule-minutes">${[10,20,30].map(n=>`<option value="${n}" ${Number(scheduleForm.minutes)===n?'selected':''}>${n} ${t('分钟','min')}</option>`).join('')}</select></div><div class="field"><label for="schedule-activity">${t('运动类型','Activity')}</label><select id="schedule-activity">${ACTIVITY_IDS.map(id=>`<option value="${id}" ${scheduleForm.activity===id?'selected':''}>${activityLabel(id)}</option>`).join('')}</select></div></div><p class="helper">${t('未选的日子不自动标记休息。保存后可在日期明细里取消尚未开始的预约。','Unselected days are not automatically marked as rest. Cancel future reservations in date details.')}</p><div class="modal-actions"><button class="secondary" data-action="report">${t('先不安排','Not now')}</button><button class="primary" data-action="schedule-preview">${t('核对安排','Review dates')}</button></div>`,t('下周建议','NEXT WEEK')),'schedule');}
function previewSchedule(){scheduleForm={dates:Array.from(document.querySelectorAll('[data-schedule-date]:checked:not(:disabled)')).map(el=>el.dataset.scheduleDate),minutes:Number($('#schedule-minutes').value),activity:$('#schedule-activity').value};scheduleReview=journey.scheduleDraft(state,scheduleForm.dates,scheduleForm.minutes,scheduleForm.activity);if(!scheduleReview){toast(t('至少选一天，再核对安排。','Choose at least one day to continue.'));return;}showScheduleConfirm();}
function showScheduleConfirm(){if(!scheduleReview)return;openModal(modalShell(`<h2 id="modal-title">${t('确认后，加入下周。','Confirm to add these dates.')}</h2><ul class="schedule-summary">${scheduleReview.dates.map(date=>`<li>${displayDate(date)} · ${scheduleReview.minutes} ${t('分钟','min')} ${activityLabel(scheduleReview.activity)}</li>`).join('')}</ul><p>${t('只添加上面这些安排，不开启提醒，不改动已有记录。','Only these plans will be added. Notifications stay off and existing records stay intact.')}</p><div class="modal-actions"><button class="secondary" data-action="schedule-edit">${t('再改一下','Edit')}</button><button class="primary" data-action="schedule-confirm">${t('确认加入下周','Add to next week')}</button></div>`,t('核对安排','REVIEW PLANS')),'schedule-confirm');}
function confirmSchedule(){const result=journey.applySchedule(state,scheduleReview);if(!result.ok){toast(t('安排已经变化，请重新核对。','Plans changed. Please review again.'));scheduleForm=null;scheduleReview=null;showSchedule();return;}scheduleReview=null;scheduleForm=null;closeModal();weekOffset=1;render();showRecords();persistNotice(t(`已添加 ${result.added.length} 天安排，保留 ${result.kept.length} 天已有安排。`,`New plans: ${result.added.length}. Existing plans preserved: ${result.kept.length}.`));}

function startComeback(energy){if(state.plan.done||todayCare()?.done){startIssue('return');return;}comebackDraft=comeback.begin(state,energy);if(comebackDraft){if(comebackDraft.energy==='ready'||comebackDraft.energy==='rest')showComebackReview();else showComebackReason();}}
function showComebackEnergy(){openModal(modalShell(`<h2 id="modal-title">${t('今天想怎么安排？','What works for today?')}</h2><p class="modal-sub">${t('照常练、少做一点或休息，都由你决定。','Keep your plan, choose a shorter session or rest.')}</p><div class="adjust-energy-list">${Object.entries(energyData).map(([id,e])=>`<button class="option" data-energy="${id}">${icon(e.glyph)}<span><strong>${pair(e.title)}</strong><small>${pair(e.sub)}</small></span></button>`).join('')}</div>`,t('再调一调','Adjust again')),'comeback-energy');}
function showComebackReason(){const e=energyData[comebackDraft.energy];openModal(modalShell(`<div class="modal-kora">${portrait()}<span>${pair(persona().label)} Kora · ${pair(e.title)}</span></div><h2 id="modal-title">${t('今天想怎么调整？','What would help today?')}</h2><p class="modal-sub">${t('选最接近的情况就好。确认之前，原计划不会改变。','Choose what fits. Your plan stays unchanged until you confirm.')}</p><div class="return-reasons">${Object.keys(issueLabels).map(id=>`<button class="reason-choice" data-comeback-reason="${id}" aria-pressed="${comebackDraft.reason===id}">${icon(issueIcons[id])}${pair(issueLabels[id])}</button>`).join('')}</div><div class="reason-response" aria-live="polite">“${say(comebackDraft.reason)}”</div><button class="primary" data-action="comeback-review">${t('看看可选安排','See my options')} ${icon('arrow')}</button><p class="helper">${t('不想做任何安排？关掉也可以。','No plan today? You can close this, too.')}</p>`,t('听听今天的你','Meet today’s you'),1),'comeback-reason');}
function showComebackReview(){const d=comebackDraft,p=comeback.plan(state,d);openModal(modalShell(`<div class="modal-kora">${portrait()}<span>${pair(persona().label)} Kora</span></div><h2 id="modal-title">${d.energy==='ready'?t('今天，按你的节奏走。','Today, at your pace.'):d.energy==='rest'?t('今天，不安排训练。','No training plan for today.'):t('把“大计划”，折小一点。','Fold that big plan into something small.')}</h2><p class="modal-sub">${d.energy==='low'?t('二选一就好。做完就停，不补过去的。','Choose just one. Stop when done. Nothing to make up.'):d.energy==='rest'?t('取消今天未完成的训练，餐食记录照常保留。','Remove today’s unfinished session and keep your food records.'):state.plan.type==='rest'?t('按档案中的运动和时长偏好恢复训练。','Resume using the activity and duration in your profile.'):t('保留当前安排，准备好就可以开始。','Keep your current plan and start when you’re ready.')}</p>${d.energy==='low'?`<div class="tiny-options">${['walk','stretch'].map(action=>`<button data-comeback-action="${action}" aria-pressed="${d.action===action}">${icon(action==='walk'?'walk':'yoga')}<strong>${smallTitle({type:'tiny',action})}</strong><small>${action==='walk'?t('走到窗边，或在房间里走走','To the window, or around your room'):t('在舒服的范围内，慢慢活动','Move slowly, within a comfortable range')}</small></button>`).join('')}</div>`:''}<div class="return-review"><small>${t('确认后，今天的安排','Your arrangement after confirmation')}</small><strong>${d.energy==='rest'?t('今天休息','Rest today'):smallTitle(p)}</strong><p>${d.energy==='ready'?t('正常训练不需要说明原因。已有预约会保留。','No explanation needed for your usual session. Existing reservations stay.'):t('替换今天未完成的训练，餐食记录保留。当前预览不发送通知。','Replaces today’s unfinished session. Food records stay. This preview does not send notifications.')}</p></div>${d.energy!=='ready'?reservationChoice(d):''}<div class="modal-actions"><button class="text-link" data-action="comeback-back">${t('先不改','Keep current plan')}</button><button class="primary" data-action="comeback-confirm">${t('确认这个安排','Confirm this plan')} ${icon('check')}</button></div>`,t('一起确认','Decide together')),'comeback-review');}
function confirmComeback(){if(!comeback.confirm(state,comebackDraft)){closeModal();toast(t('安排或日期已经变化，请重新选择。已有记录没有被覆盖。','The date or plan changed. Please choose again. Existing records were kept.'));return;}comebackDraft=null;const saved=save();render();showComebackSuccess();if(!saved)toast(t('浏览器未能保存，仅本次页面保留。','Could not save. This arrangement lasts only for this session.'));}
function showComebackSuccess(){openModal(modalShell(`<div class="success">${portrait(state.profile.persona,'success-art')}<h2 id="modal-title">${t('安排好了。','Your plan is updated.')}</h2><p class="modal-sub">${routineSpeech()}</p><p>${t('回到首页就能查看。想恢复训练或再次调整，随时可以改。','You can see it on Today. Resume training or adjust again whenever you need to.')}</p><button class="primary" data-action="back-today">${t('回到我的今天','Back to my day')} ${icon('arrow')}</button></div>`,t('调整完成','Plan updated')),'comeback-success');}

function routineSpeech(){if(state.plan.done)return t('今天的计划完成了。剩下的时间，去做点你喜欢的。','Today’s plan is done. Enjoy the rest of your day.');if(state.plan.type==='rest')return t('今天按休息安排来。有想法了，我们再调整。','Today is a rest day. We can adjust if you change your mind.');if(state.plan.type==='reschedule')return t('训练已经改期。今天不用补做。','Your session has been moved. No need to make it up today.');if(state.plan.session)return t('已经开始了。按自己的节奏来，我在这儿。','You’ve started. Go at your own pace; I’m here.');return pair({calm:['嗯，安排好了。准备好就开始。','All set. Start when you’re ready.'],snark:['计划已经写好了，这次让运动服也参与一下？','The plan is ready. Shall we give your workout clothes a turn?'],fiery:['准备好了就出发！今天按计划来！','Ready? Let’s go! Today, we follow the plan!'],gentle:['今天的安排准备好了。开始的时候，叫上我。','Your plan is ready. Let me know when you’re starting.']}[state.profile.persona]||['准备好了就开始。','Start when you’re ready.']);}
function sessionTime(){const seconds=Math.floor(calendar.elapsed(state.plan)/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function showSession(){if(state.plan.done||['rest','reschedule'].includes(state.plan.type))return;const running=state.plan.session?.running;openModal(modalShell(`<div class="session-head">${portrait()}<div><p class="eyebrow">${running?t('训练进行中','SESSION IN PROGRESS'):t('已暂停','PAUSED')}</p><h2 id="modal-title">${planTitle()}</h2></div></div><div class="session-clock"><span data-session-clock>${sessionTime()}</span><small>${t('已计时 · 到时不会自动标记完成','Elapsed time · completion is always your choice')}</small></div><ol class="session-steps"><li>${t('准备好你熟悉的动作或已选好的跟练内容。','Get your familiar routine or chosen workout ready.')}</li><li>${t('按适合自己的节奏进行，需要时可以暂停。','Go at your own pace and pause whenever you need to.')}</li><li>${t('结束后点“完成训练”，记录今天的行动。','When you finish, select “Complete session” to record it.')}</li></ol><p class="helper">${t('这是计时和记录工具，尚未提供完整跟练课程。关掉弹窗会继续计时；想停下来请先暂停。','This is a timer and log, not a guided workout. Closing this panel leaves the timer running; pause it to take a break.')}</p><div class="modal-actions"><button class="secondary" data-action="${running?'pause-session':'start-session'}">${running?t('暂停一下','Pause'):t('继续训练','Resume')}</button><button class="primary" data-action="training-done">${t('完成训练','Complete session')}</button></div><button class="text-link" data-action="close">${t('返回首页','Back to Today')}</button>`,t('跟着自己的节奏','AT YOUR PACE')),'session');}
function showComplete(){const done=state.plan.done;if(['rest','reschedule'].includes(state.plan.type))return;openModal(modalShell(`<h2 id="modal-title">${done?t('取消完成标记？','Remove the completion mark?'):t('今天的训练完成了吗？','Finished today’s session?')}</h2><p class="modal-sub">${planTitle()}</p><p>${done?t('只更正记录，不会开启提醒。','This only corrects your record. It will not enable reminders.'):t('以你实际完成的情况为准，计时不会替你打卡。','Record what you actually did. The timer never marks a session complete for you.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${t('先返回','Go back')}</button><button class="primary" data-action="${done?'uncomplete-session':'complete-session'}">${done?t('取消标记','Remove mark'):t('完成了，记下来','Yes, record it')}</button></div>`,t('训练记录','SESSION RECORD')),'complete');}
const foods=[{id:'rice',name:['熟米饭','Cooked rice'],cal:130},{id:'banana',name:['香蕉','Banana'],cal:89},{id:'egg',name:['水煮鸡蛋','Boiled egg'],cal:155},{id:'chicken',name:['熟鸡胸肉','Cooked chicken breast'],cal:165},{id:'broccoli',name:['熟西兰花','Cooked broccoli'],cal:35},{id:'oat',name:['原味干燕麦','Plain dry oats'],cal:389}];
const recipes=[{name:['燕麦、香蕉与蓝莓','Oats, banana & blueberries'],sub:['温暖一点，早晨也慢一点。','A warm, unhurried morning.'],detail:['燕麦加热后放入香蕉和蓝莓；按喜好选择奶或植物饮品。','Warm the oats, add banana and blueberries, and use milk or a plant drink you enjoy.'],note:['含燕麦；使用奶时注意乳制品相关忌口。','Contains oats. Check dairy restrictions when adding milk.']},{name:['蔬菜三文鱼碗','Salmon & vegetable bowl'],sub:['把喜欢的颜色，放进同一碗。','A bowl of colors you enjoy.'],detail:['搭配熟米饭、充分烹熟的三文鱼和喜欢的蔬菜。','Combine cooked rice, thoroughly cooked salmon and vegetables you enjoy.'],note:['含鱼类，请按已确认的过敏与忌口替换。','Contains fish. Adapt to known allergies and dietary restrictions.']},{name:['鸡蛋杂粮饭','Egg & whole-grain rice'],sub:['家里有的食材，也能好好吃。','A good meal with what is at home.'],detail:['用熟杂粮饭、全熟鸡蛋与蔬菜组合。','Combine cooked whole grains, fully cooked eggs and vegetables.'],note:['含鸡蛋，份量按实际需要决定。','Contains eggs. Choose portions that fit your needs.']}];
function foodName(log){const f=foods.find(f=>f.id===log.foodId||f.name[0]===log.name||f.name[1]===log.name);return f?pair(f.name):log.name;}
function food(){return `${intro(t('饮食','Food'),t('好好吃饭。','Food is care.'),t('记下这一餐，看看下一餐的灵感。','Log this meal. Find ideas for the next.'))}${koraNote('food')}<div class="two-col"><section class="panel"><h3>${t('记下这一餐','Log a meal')}</h3><form id="food-form" novalidate><div class="inline-form"><div class="field"><label class="label" for="food-name">${t('吃了什么','Food')}</label><select id="food-name">${foods.map(f=>`<option value="${f.id}">${pair(f.name)}</option>`).join('')}</select></div><div class="field"><label class="label" for="food-grams">${t('实际份量 / 克','Portion / grams')}</label><input id="food-grams" type="number" min="1" max="2000" value="100" required></div></div><div class="estimate"><strong id="food-estimate">130</strong><span>kcal</span><small>${t('按份量估算','Estimated from portion')}</small></div><button class="primary" type="submit">${t('保存这一餐','Save meal')} ${icon('check')}</button><p class="helper">${t('此处为演示营养值，尚未接入正式数据库。烹饪方式和配料会影响实际热量。','Sample nutrition values, not a connected database. Cooking methods and ingredients affect actual calories.')}</p></form></section><section class="panel"><div class="plan-header"><h3>${t('今天的餐食记录','Today’s meal log')}</h3><span>${state.logs.length} ${t('条','entries')}</span></div>${state.logs.length?state.logs.map(l=>`<div class="log-item"><div><strong>${escapeHTML(foodName(l))}</strong><small>${l.grams} g · ${t('估算','est.')} ${l.cal} kcal</small></div><button data-delete-log="${escapeHTML(l.id)}" aria-label="${t('删除','Delete ')+escapeHTML(foodName(l))}">${t('删除','Delete')}</button></div>`).join(''):`<div class="empty kora-empty">${portrait(state.profile.persona)}<p>${t('还没有记录。<br>从这一餐开始就好。','Nothing logged yet.<br>Start with this meal.')}</p></div>`}<p class="helper">${t('只呈现已记录内容，不据此评价全天饮食。','Only logged meals are shown. This is not an assessment of your whole day.')}</p></section></div><div class="section-head" style="margin-top:36px"><h2>${t('下一餐的灵感','Ideas for your next meal')}</h2><span class="helper">${t('示例搭配','Sample combinations')}</span></div><div class="recipe-grid">${recipes.map((r,i)=>`<article class="recipe"><div class="recipe-art">${plate(i).replace('示意餐盘插画',t('示意餐盘插画','Illustrated sample meal'))}</div><div class="card-body"><h3>${pair(r.name)}</h3><p>${pair(r.sub)}</p><button class="text-link" data-recipe="${i}">${t('看看这份搭配','See this idea')} ↗</button></div></article>`).join('')}</div>`;}
const workouts=[{id:'light',name:['低冲击有氧','Low-impact cardio'],minutes:10,kind:'cardio',noJump:true,glyph:'walk',author:'growingannanas',url:'https://www.youtube.com/@growingannanas'},{id:'strength',name:['自重力量训练','Bodyweight strength'],minutes:20,kind:'strength',noJump:false,glyph:'move',author:'Pamela Reif',url:'https://www.youtube.com/@PamelaRf1'},{id:'stretch',name:['全身舒展','Full-body stretch'],minutes:10,kind:'stretch',noJump:true,glyph:'yoga',author:'Yoga With Adriene',url:'https://www.youtube.com/@yogawithadriene'}];
function filterLabel(id){return id==='all'?t('全部','All'):id==='noJump'?t('不跳跃','No jumping'):activityLabel(id);}
function move(){const ordered=[...workouts].sort((a,b)=>(Number(state.profile.noJump&&b.noJump)+Number(state.profile.activities.includes(b.kind)))-(Number(state.profile.noJump&&a.noJump)+Number(state.profile.activities.includes(a.kind))));const items=filter==='all'?ordered:ordered.filter(w=>w.kind===filter||(filter==='noJump'&&w.noJump));return `${intro(t('运动','Move'),t('选好内容，开始运动。','Choose a session. Get moving.'),t('按今天的时间和状态，选择一个安排。','Choose a plan that fits today’s time and energy.'))}${koraNote('move')}<p class="preference-line">${t('你喜欢：','Your interests: ')}${state.profile.activities.map(activityLabel).join(' · ')} <button class="text-link" data-route="profile">${t('修改','Edit')}</button></p><div class="filter-bar">${['all','cardio','strength','stretch','noJump'].map(id=>`<button class="filter-chip ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${filterLabel(id)}</button>`).join('')}</div><div class="exercise-grid">${items.map(w=>`<article class="exercise-card"><div class="exercise-art">${icon(w.glyph)}<span class="duration">${w.minutes} MIN</span></div><div class="card-body"><h3>${pair(w.name)}</h3><div class="tags"><span>${w.noJump?t('不跳跃','No jumping'):t('力量','Strength')}</span><span>${t('无器械','No equipment')}</span></div><p>${t('演示安排','Demo session')} · ${w.minutes} ${t('分钟','min')}<br>${t('作者频道参考：','Creator channel: ')}${w.author}</p><div class="exercise-actions"><button class="secondary" data-workout="${w.id}">${t('调整为这个安排','Use this session')}</button><a class="text-link" href="${w.url}" target="_blank" rel="noopener noreferrer">${t('作者频道','Creator channel')} ↗</a></div></div></article>`).join('')}</div><div class="gentle-note">${t('这些是原型训练卡片，外链仅到作者频道，尚未核验具体视频。运动偏好用于排序，不代表已进行适用性评估。','These are sample sessions. Links open creator channels, not verified videos. Preferences affect ordering, not an assessment of suitability.')}</div><button class="text-link" data-issue="tired">${t('今天想休息一下','Take a rest today')} ${icon('arrow')}</button>`;}
function chat(){return `${intro(t('聊聊','Chat'),t('我在，慢慢说。','I’m here. Take your time.'),t('今天过得怎么样？','How has your day been?'))}<div class="chat-layout"><section class="chat-panel"><div class="chat-status">${portrait(state.profile.persona)}<div><strong>${pair(persona().label)} Kora</strong><small>${t('情境演示 · 未接入 AI','Scripted demo · AI not connected')}</small></div><button class="text-link change-persona" data-route="profile">${t('换性格','Switch')}</button></div><div class="messages" id="messages" role="log" aria-live="polite">${chatMessages()}</div><form class="chat-input" id="chat-form"><input id="chat-text" maxlength="500" placeholder="${t('比如：今天加班，只剩10分钟……','Try: I only have 10 minutes today…')}" aria-label="${t('告诉 Kora 今天的状态','Tell Kora how you feel')}" autocomplete="off"><button type="submit" aria-label="${t('发送消息','Send message')}">${icon('send')}</button></form><div class="chat-helper">${t('对话仅在当前页面内存中保留，不上传。','Messages stay in this page’s memory and are not uploaded.')}</div></section><aside class="companion-panel">${portrait(state.profile.persona)}<h3>${pair(persona().label)} Kora</h3><p>${pair(persona().tag)}</p><div class="quick-prompts">${['time','return','guilt','tired'].map(id=>`<button data-prompt="${id}">${pair(issueLabels[id])}</button>`).join('')}</div></aside></div>`;}
function replyBody(topic,id){if(topic==='completed')return t('做完了，真好！如果今天的计划确实完成了，可以回首页记下来；我不会只凭这句话自动打卡。','Nice work! If today’s session is finished, you can record it on Today. I won’t mark it complete from a message alone.');if(topic==='injury')return t('先暂停当前训练，不要忍痛继续。这个原型不能判断伤情。疼痛明显、不能负重或症状加重时，请寻求专业医疗评估；紧急情况请联系当地急救服务。','Pause the activity rather than pushing through pain. This prototype cannot assess injuries. Seek medical assessment for significant pain, inability to bear weight or worsening symptoms; contact local emergency services for emergencies.');const extra={time:['可以缩短为10分钟、休息或改到明天。我先列出改动，你来决定。','We can try ten minutes, rest, or move it to tomorrow. You review the changes first.'],tired:['想调整的话，我们一起看看休息或轻活动的选项。','If you want, we can look at rest or gentle movement.'],return:['不补练。只看看今天适合哪一种安排。','No catch-up exercise. Just a plan that fits today.'],guilt:['不用少吃一餐或多练来补偿。想说说感受，我也在。','No skipped meals or extra exercise to compensate. I can listen, too.'],fallback:['这里是预设情境演示。可以试试没时间、疲劳、中断或吃完自责；开放式 AI 对话还未接入。','This is a scripted demo. Try time pressure, tiredness, a break in your routine or food guilt. Open-ended AI chat is not connected.']};return say(topic,id)+'\n'+pair(extra[topic]||extra.fallback);}
function chatMessages(){return `<div class="message">${escapeHTML(say('hello'))}</div>`+chats.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='user'?escapeHTML(m.text):`<small class="reply-persona">${pair(persona(m.persona).label)} Kora</small>${escapeHTML(replyBody(m.topic,m.persona))}`}${m.role!=='user'&&issueLabels[m.topic]?`<br><button class="primary" ${m.topic==='return'?'data-energy="low"':`data-issue="${m.topic}"`}>${t('一起看看可选安排','Explore the options')} ${icon('arrow')}</button>`:''}</div>`).join('');}
function profile(){const p=profileDraft||state.profile;return `${intro(t('我的档案','My profile'),t('你的日常，你来决定。','Your everyday. Your way.'),t('首次填写的资料都在这里，随时可以修改。','Everything from setup is here. Change it whenever you need.'))}${lifeProfile()}${motionSettings()}<div class="profile-scenery"><span>${t('我的路线背景','My trail background')} · ${pair(sceneNames[currentScene()])}</span><button class="text-link" data-action="trail-reward">${t('选择背景','Choose a background')} ↗</button></div><section class="profile-personality"><div class="section-head"><h2>${t('我的 Kora','My Kora')}</h2><span class="helper">${t('选择后，点击下方保存生效','Choose, then save below to apply')}</span></div>${personaCards(p.persona,true)}</section><div class="profile-layout"><section class="panel"><div class="profile-avatar">${portrait(p.persona)}<div><h2>${t('我的基本资料','My details')}</h2><small>${t('与首次设置同步','Synced from your first setup')}</small></div></div><form id="profile-form" novalidate>${profileFields(p)}<p class="form-error" id="form-error" role="alert"></p><button class="primary" type="submit">${t('保存我的档案','Save my profile')} ${icon('check')}</button></form></section><section class="panel"><h3>${t('你始终掌握选择权','You stay in control')}</h3><ul class="privacy-list"><li>${t('资料留在这个浏览器','Your details stay here')}<small>${t('昵称、身高、体重、偏好和演示记录仅存于此浏览器，没有账号或云同步。','Name, height, weight, preferences and demo records are stored in this browser only. No account or cloud sync.')}</small></li><li>${t('性格变，边界不变','Different voices. Same care.')}<small>${t('不羞辱身材，不鼓励节食或忍痛训练。修改档案不会自动改写已有计划。','No body shaming, restrictive dieting or training through pain. Profile edits do not automatically rewrite your plan.')}</small></li><li>${t('历史是参考，不是标签','History is a reference')}<small>${t('计划和餐食按日期保存，旧版无日期记录单独保留。','Plans and meals are saved by date. Earlier undated records are kept separately.')}</small></li></ul>${state.legacy?`<button class="secondary" data-action="legacy">${t('查看旧版无日期记录','View undated earlier records')}</button>`:''}<div><button class="danger" data-action="reset">${t('清除本地数据，重新开始','Clear local data & start again')}</button></div><p class="helper">${storageOK?t('本地保存可用。','Local storage available.'):t('本地保存不可用，仅本次页面保留。','Local storage unavailable. Session only.')}</p></section></div><section class="soft-banner"><p>${t('Kora 可以和你一起变化。','Kora can grow alongside you.')}</p><small>${t('体型联动仍是待讨论方向。当前身高和体重只作档案记录，不计算目标体型、减重期限或自动改变考拉体型。','Body-shape linking remains a future idea. Measurements are profile records only; they do not calculate a target body, weight-loss timeline or change Kora’s shape.')}</small></section>`;}

function openModal(content,view){if(!$('#modal').open)modalOpener=document.activeElement;modalView=view;$('#modal').classList.toggle('task-sheet',['today-plan','adjust-reason','not-well','session','complete','choices','confirm','success','comeback-energy','comeback-review','comeback-success','life-plan'].includes(view));$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){comebackDraft=null;draft=null;lifePlanDraft=null;modalView=null;$('#modal').close();if(modalOpener?.isConnected)modalOpener.focus();}
function modalShell(content,kicker=t('调整计划','Adjust plan'),step=0){return `<div class="modal-inner"><div class="modal-top"><span class="eyebrow">${kicker}</span><div class="modal-tools">${languageControl()}<button class="close" data-action="close" aria-label="${t('关闭','Close')}">×</button></div></div>${step?`<div class="steps" aria-label="${t('第'+step+'步，共3步','Step '+step+' of 3')}">${[1,2,3].map(n=>`<span class="${n<=step?'active':''}"></span>`).join('')}</div>`:''}${content}</div>`;}
function startIssue(issue){if(state.plan.done||todayCare()?.done){openModal(modalShell(`<h2 id="modal-title">${t('已经完成的，保留就好。','Keep what you have already done.')}</h2><p class="modal-sub">${t('不把已经完成的行动改写成休息或改期。可以先聊聊，明天再做新安排。','Completed activities will not be replaced with rest or rescheduled. Let us talk, or plan another day.')}</p><button class="primary" data-action="go-chat">${t('和 Kora 聊聊','Talk to Kora')}</button>`),'completed');return;}draft={issue,choice:null,date:state.date,base:JSON.stringify(state.plan)};showChoices();}
function reservationChoice(d){if(state.plan.type!=='reschedule'||!state.plan.targetDate)return '';const key=state.plan.targetDate,locked=state.days[key]?.plan?.done||state.days[key]?.comeback;return `<div class="reservation-choice"><strong>${t('还有一个明天的预约','You also have a session booked for tomorrow')}</strong><p>${displayDate(key)} · ${planTitle(state.days[key]?.plan||state.plan)}</p><label><input type="radio" name="reservation" data-reservation="keep" ${!d.cancelReservation?'checked':''}> ${t('保留明天的训练','Keep tomorrow’s session')}</label><label><input type="radio" name="reservation" data-reservation="cancel" ${d.cancelReservation?'checked':''} ${locked?'disabled':''}> ${t('同时取消明天这次预约','Also cancel this reservation')}</label>${locked?`<small>${t('明天已有完成或状态记录，不能在这里取消。','Tomorrow has a completion or check-in record, so it cannot be cancelled here.')}</small>`:''}</div>`;}
function reservationSummary(d){return state.plan.type==='reschedule'?t(d.cancelReservation?'同时取消此前移到明天的预约。':'明天的预约保持不变。',d.cancelReservation?'The reservation moved to tomorrow will also be cancelled.':'Tomorrow’s reservation stays in place.'):t('其他日期的安排保持不变。','Plans on other dates stay unchanged.');}
function planChangeOptions(d){return {cancelReservation:Boolean(d?.cancelReservation)};}
function showChoices(){const guilt=draft.issue==='guilt';openModal(modalShell(`<div class="modal-kora">${portrait(state.profile.persona)}<span>${pair(persona().label)} Kora</span></div><h2 id="modal-title">${draft.issue==='adjust'?t('今天不太想练？换个合适的安排。','Not up for your usual session? Let’s find what fits.'):say(draft.issue)}</h2><p class="modal-sub">${t('先选一个适合现在的安排。确认之前，不会改变计划。','Choose what fits right now. Nothing changes until you confirm.')}</p>${guilt||draft.issue==='adjust'?`<button class="option" data-action="go-chat">${icon('chat')}<span><strong>${t('先聊聊，不改计划','Just talk, keep the plan')}</strong><small>${t('不用把情绪立刻变成任务。','Feelings do not have to become a task.')}</small></span></button>`:''}${(guilt?['rest']:['short','rest','reschedule']).map(option).join('')}<div class="modal-actions"><button class="text-link" data-action="close">${t('保持原计划','Keep current plan')}</button></div>`,t('选择安排','Choose a plan')),'choices');}
function option(id){const short=calendar.shorter(state),data={short:['walk',['换成短一点的','Choose a shorter session'],[planTitle(short),planTitle(short)]],rest:['moon',['今天休息','Rest today'],['今天不安排训练，饮食照常','No training today; eat as usual']],reschedule:['refresh',['改到明天','Move to tomorrow'],['先查看明天是否已有安排','We’ll check tomorrow’s existing plans first']] }[id];return `<button class="option" data-choice="${id}">${icon(data[0])}<span><strong>${pair(data[1])}</strong><small>${pair(data[2])}</small></span><span class="radio"></span></button>`;}
function draftPlan(){if(draft.workout){const w=workouts.find(w=>w.id===draft.workout);return {type:'custom',action:w.kind,workout:w.id,minutes:w.minutes,done:false,reminder:false};}if(draft.choice==='resume')return calendar.defaultPlan(state);if(draft.choice==='rest')return {type:'rest',minutes:0,done:false,reminder:false};if(draft.choice==='reschedule')return {...(state.plan.type==='rest'?calendar.defaultPlan(state):state.plan),type:'reschedule',done:false,reminder:false};return calendar.shorter(state);}
function showConfirm(){const next=draftPlan();openModal(modalShell(`<h2 id="modal-title">${t('确认今天的安排','Review your plan')}</h2><div class="compare"><div><small>${t('现在','Current')}</small><strong>${planTitle()}</strong></div><span>→</span><div><small>${t('调整后','Proposed')}</small><strong>${planTitle(next)}</strong></div></div>${reservationChoice(draft)}<p class="gentle-note">${next.type==='reschedule'?t('今天的训练移到明天；如果明天已有计划，不会覆盖。','Move today’s session to tomorrow. An existing plan will never be overwritten.'):reservationSummary(draft)} ${t('餐食记录保留，确认后可撤销。计时中的训练会停止。','Food records stay. You can undo the change. Any running session will stop.')}</p><div class="modal-actions"><button class="text-link" data-action="close">${t('先不改','Keep current plan')}</button><button class="primary" data-action="confirm-plan">${t('确认调整','Confirm change')}</button></div>`,t('调整计划','Change plan')),'confirm');}
function showSuccess(){openModal(modalShell(`<div class="success">${portrait(state.profile.persona,'success-art')}<h2 id="modal-title">${t('安排已更新。','Plan updated.')}</h2><p class="modal-sub">${routineSpeech()}</p><div class="gentle-note">${t('今天与日历已同步，可撤销最近一次调整。当前预览不会发送通知。','Your plan and calendar are updated. You can undo the latest change. This preview does not send notifications.')}</div><div class="modal-actions"><button class="primary" data-action="back-today">${t('看看我的今天','Back to my day')} ${icon('arrow')}</button></div></div>`,t('调整完成','All set')),'success');}
function commitDraft(){if(!draft)return;if(draft.date!==state.date||draft.base!==JSON.stringify(state.plan)){closeModal();toast(t('计划已经变化，请重新选择。','The plan changed. Please choose again.'));return;}if(!calendar.adjust(state,draftPlan(),draft.workout||draft.issue,new Date().toISOString(),planChangeOptions(draft))){closeModal();toast(t('目标日期已有安排或记录已变化，未覆盖已有记录。','That date has a plan or records changed. Existing records were kept.'));return;}draft=null;const saved=save();render();showSuccess();if(!saved)toast(t('仅本次页面保留，浏览器未能保存。','Session only: the browser could not save this change.'));}
function showAbout(){openModal(modalShell(`<h2 id="modal-title">${t('你的 Kora，你的节奏。','Your Kora. Your pace.')}</h2><p class="modal-sub">${t('同一份陪伴，四种语气。中断后，还能继续。','One kind of care, four different voices. A fresh start whenever you need it.')}</p><div class="about-points"><p><strong>${t('01 · 先认识彼此','01 · Get to know each other')}</strong><span>${t('先做趣味测试，再选搭子语气、补资料。偏好同步到计划建议和档案。','Discover your lifestyle, choose Kora’s voice, then add your details. Results sync with home recommendations and Profile.')}</span></p><p><strong>${t('02 · 安慰，变成可执行的调整','02 · Care becomes an actionable change')}</strong><span>${t('缩短、休息、改期，确认后才更新。性格不同，照顾你的边界一致。','Shorten, rest or reschedule, after your confirmation. Different personalities share the same care.')}</span></p><p><strong>${t('03 · 在关键时刻出现','03 · There at the right moments')}</strong><span>${t('首页问候、聊天、空记录和完成反馈，都是你选的那只 Kora。','Your chosen Kora appears in greetings, chat, empty logs and completion feedback.')}</span></p></div><p class="helper">${t('这是前端原型，没有登录账号、后端或真实 AI。聊天是双语预设情境，食物和训练是演示数据。基本资料仅存于本地浏览器；没有照片评估、社群、真实通知或自动体型联动。','This is a frontend prototype without sign-in, a backend or real AI. Chat uses bilingual scripted scenarios; food and exercise data are samples. Details stay in local browser storage. Photo assessment, communities, real notifications and body-shape linking are not implemented.')}</p><div class="modal-actions"><button class="primary" data-action="close">${t('知道了','Got it')}</button></div>`,t('关于 Kora','About Kora')),'about');}
function showRecipe(n){const r=recipes[n];openModal(modalShell(`<h2 id="modal-title">${pair(r.name)}</h2><p class="modal-sub">${pair(r.detail)}</p><div class="gentle-note">${pair(r.note)}<br>${t('这是搭配灵感，不是个人营养处方。','This is a meal idea, not a personal nutrition prescription.')}</div><button class="primary" data-action="close">${t('记下这个灵感','Got the idea')}</button>`,t('餐食灵感','Meal inspiration')),'recipe:'+n);}
function showReset(){openModal(modalShell(`<h2 id="modal-title">${t('清除资料，重新开始？','Clear your details and start again?')}</h2><p class="modal-sub">${t('这会清除这个浏览器里的昵称、身高、体重、性格、偏好、餐食和计划记录，回到首次选择流程。','This clears your name, measurements, personality, preferences, meal logs and plans in this browser, then returns to setup.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${t('先保留','Keep my data')}</button><button class="primary" data-action="confirm-reset">${t('确认清除','Clear my data')}</button></div>`,t('本地数据','Local data')),'reset');}
function refreshModal(){if(modalView==='rest-checkin'){showRestCheckin();return;}if(modalView?.startsWith('week-day:')){showWeekDay(modalView.slice(9));return;}if(modalView==='today-plan'){showTodayPlan();return;}if(modalView==='adjust-reason'){showAdjustReason();return;}if(modalView==='not-well'){showNotWell();return;}if(modalView==='record-hub'){showRecordHub();return;}if(modalView==='records'){showRecords();return;}if(modalView==='rewards'){showRewards();return;}if(modalView==='report'){showReport();return;}if(modalView==='schedule'){showSchedule();return;}if(modalView==='schedule-confirm'){showScheduleConfirm();return;}if(modalView==='session'){showSession();return;}if(modalView==='complete'){showComplete();return;}if(modalView==='life-plan'){showLifePlan();return;}if(modalView==='comeback-energy'){showComebackEnergy();return;}if(modalView==='comeback-reason'){showComebackReason();return;}if(modalView==='comeback-review'){showComebackReview();return;}if(modalView==='comeback-success'){showComebackSuccess();return;}if(modalView==='choices')showChoices();else if(modalView==='confirm')showConfirm();else if(modalView==='success')showSuccess();else if(modalView==='about')showAbout();else if(modalView==='legacy')showLegacy();else if(modalView?.startsWith('history:'))showHistory(modalView.slice(8));else if(modalView==='reset')showReset();else if(modalView==='completed')startIssue('time');else if(modalView?.startsWith('recipe:'))showRecipe(Number(modalView.split(':')[1]));}
function sendChat(text){text=text.trim();if(!text)return;let topic='fallback';const checked=text.replace(/没有受伤|没受伤|不疼|不痛|not injured|no pain|not hurt/ig,'');if(/疼|痛|受伤|扭伤|流血|晕|胸闷|pain|hurt|injur|dizz|bleed|chest|faint/i.test(checked))topic='injury';else if(/完成|做完|练完|finished|completed/i.test(text)&&!/没完成|没做完|没练完|not finished|not completed/i.test(text))topic='completed';else if(/自责|吃多|暴食|胖|失败|补偿|饿|少吃|guilt|overeat|binge|fat\b|starv|skip.*meal|compensat/i.test(text))topic='guilt';else if(/加班|没时间|时间不够|只剩|忙|busy|no time|only.*minute|overtime|short on time/i.test(text))topic='time';else if(/没记录|几天|中断|回来|坚持|放弃|半途|been away|back|missed|days|restart|give up|giving up|quit/i.test(text))topic='return';else if(/累|疲|不想|休息|tired|rest|exhaust|worn out/i.test(text))topic='tired';chats.push({role:'user',text},{role:'kora',topic,persona:state.profile.persona});if(currentRoute!=='chat')route('chat');else{$('#messages').innerHTML=chatMessages();$('#messages').scrollTop=$('#messages').scrollHeight;$('#chat-text').value='';}}
function setLanguage(lang){if(!['zh','en'].includes(lang)||state.language===lang)return;hideCheer();captureForm();const foodDraft=$('#food-form')?{id:$('#food-name').value,grams:$('#food-grams').value}:null;const restMoodDraft=$('#rest-mood')?.value;const chatDraft=$('#chat-text')?.value;state.language=lang;save();render();if(foodDraft){$('#food-name').value=foodDraft.id;$('#food-grams').value=foodDraft.grams;updateEstimate();}if(chatDraft!==undefined&&$('#chat-text'))$('#chat-text').value=chatDraft;refreshModal();if(restMoodDraft!==undefined&&$('#rest-mood'))$('#rest-mood').value=restMoodDraft;$('#toast').classList.remove('toast-visible');$('#toast').innerHTML='';}
function lifeStyle(id){const d=lifestyle.types[id];return `--life-soft:${d.soft};--life-color:${d.color}`;}
function lifeArt(id,cls=''){return `<img class="${cls}" src="assets/kora-life-${id}-v4.png" alt="${escapeHTML(pair(lifestyle.types[id].name)+' Kora')}">`;}
function lifeGallery(){return `<div class="life-gallery">${Object.entries(lifestyle.types).map(([id,d])=>`<article class="life-tile" style="${lifeStyle(id)}">${lifeArt(id)}<small>${d.code}</small><h2>${pair(d.name)}</h2><p>${pair(d.tag)}</p></article>`).join('')}</div>`;}
function lifeName(r){return r.balanced?t('节奏稳定，不急着归类','A steady rhythm'):pair(lifestyle.types[r.type].name)+(r.mixed?t(' · 混合倾向',' · mixed style'):'');}
function lifeQuote(r){return r.balanced?t('大多数时候按计划来，偶尔调整也没关系。','You usually follow through, with room to adjust.'):pair(lifestyle.types[r.type].quote);}
function lifeCare(r){return r.balanced?t('继续按适合你的计划来。需要帮忙时，再叫我。','Keep the routine that works for you. I’m here when you need a hand.'):pair(lifestyle.types[r.type].care);}
function lifeEvidence(r){if(r.version!==2)return `<p class="helper">${t('这是之前 6 题的结果，可选择重测新版。','This is your earlier 6-question result. You can try the new quiz anytime.')}</p>`;const mixed=!r.balanced&&r.secondary?.length?`<p>${t('你也有一点：','You also lean toward: ')}${r.secondary.map(id=>pair(lifestyle.types[id].name)).join(' / ')}</p>`:'';return `<div class="life-evidence"><strong>${t('为什么这样说？','What in your answers led here?')}</strong><ul>${r.evidence.map(i=>`<li>${escapeHTML(pair(lifestyle.questions[i].options.find(o=>o.id===r.answers[i]).label))}</li>`).join('')}</ul>${mixed}</div>`;}
function lifeFacts(r){return `<div class="life-facts"><span>${r.activities.map(activityLabel).join(' / ')}</span><span>${r.minutes} ${t('分钟','min')}</span><span>${pair(lifestyle.timeLabels[r.preferredTime]||lifestyle.timeLabels.flexible)}</span>${r.reminderPreference?`<span>${pair(lifestyle.reminderLabels[r.reminderPreference]||lifestyle.reminderLabels.gentle)}</span>`:''}</div>`;}
function saveQuizDraft(){try{if(quizSession)sessionStorage.setItem('kora.quiz.draft',JSON.stringify(quizSession));else sessionStorage.removeItem('kora.quiz.draft');}catch{}}
function quizRender(){saveQuizDraft();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function beginQuiz(){captureForm();quizSession={version:2,phase:'intro',index:0,answers:[]};quizRender();}
function quizView(){
 const q=quizSession||{phase:'intro',index:0,answers:[]};
 const top=`<div class="life-top"><span class="eyebrow">KORA / ${t('找到你的节奏','FIND YOUR RHYTHM')}</span>${state.onboarded?`<button class="text-link" data-life="exit">${t('先返回，不保存','Leave without saving')} ×</button>`:''}</div>`;
 if(q.phase==='intro')return `<section class="life-page">${top}<div class="life-intro"><p class="eyebrow">${t('不是每只考拉，都用同一种方式坚持。','EVERY KORA HAS A DIFFERENT WAY TO KEEP GOING.')}</p><h1>${t('你和哪只考拉，<br>比较合拍？','Which Kora<br>gets your rhythm?')}</h1><p>${t('12 道日常小问题，看看怎样安排和提醒更适合你。','12 everyday questions to find the planning and support that suit you.')}</p></div>${lifeGallery()}<div class="life-start"><button class="primary" data-life="start">${t('测测我的考拉人格','Meet my Kora type')} ${icon('arrow')}</button><p class="life-disclaimer">${t('分 3 小节 · 可返回修改 · 本标签页保留进度<br>趣味偏好测试，不是 MBTI 或心理测评。','3 short sections · Go back anytime · Progress saved in this tab<br>A playful preference quiz, not an MBTI or psychological assessment.')}</p></div></section>`;
 if(q.phase==='result'){
  const r=lifestyle.result(q.answers);if(!r)return '';
  const d=lifestyle.types[r.type];
  return `<section class="life-page">${top}<div class="life-result" style="${lifeStyle(r.type)}"><div class="life-result-art">${r.balanced?portrait('calm'):lifeArt(r.type)}<span>${r.balanced?'YOUR RHYTHM':d.code} / KORA</span></div><div><p class="eyebrow">${t('根据这次的回答，你目前……','BASED ON YOUR ANSWERS, RIGHT NOW…')}</p><h1>${lifeName(r)}<span class="sr-only"> Kora</span></h1><p class="life-result-quote">“${lifeQuote(r)}”</p><p class="life-result-care">${lifeCare(r)}</p>${lifeFacts(r)}${lifeEvidence(r)}<p class="life-disclaimer">${t('前 8 题了解习惯，后 4 题设置偏好。类型接近时会一起显示；训练时长由你的时间决定，不按人格限制。','The first 8 questions explore habits; the last 4 set preferences. Close matches are shown together. Your available time, not your type, sets session length.')}</p><div class="life-actions"><button class="primary" data-life="accept">${state.onboarded?t('保存结果和偏好','Save my result & preferences'):t('下一步，选我的陪伴搭子','Next, choose my companion')} ${icon('arrow')}</button><button class="text-link" data-life="restart">${t('重新测一次','Take it again')}</button><button class="text-link" data-life="download">${t('保存人格卡片','Save my type card')} ↓</button></div><p class="life-disclaimer">${state.onboarded?t('保存会更新运动与时长偏好；已有计划和历史记录保留。','Saving updates movement and time preferences. Existing plans and history stay.'):t('你是哪种考拉，和搭子用什么语气陪你，可以自由搭配。','Your Kora type and your companion’s voice are yours to mix and match.')}</p><p id="life-export-status" role="status"></p></div></div><details class="life-all-types"><summary>${t('认识另外几只考拉','Meet the other Kora types')}</summary>${lifeGallery()}</details></section>`;
 }
 const question=lifestyle.questions[q.index],selected=q.answers[q.index],art=['lazy','spark','busy','feel'][Math.floor(q.index/3)];
 return `<section class="life-page">${top}<div class="life-question"><aside class="life-question-art">${lifeArt(art)}<p>${t('按平时的情况选就行。','Choose what sounds like your usual day.')}</p></aside><div><div class="life-progress" aria-label="${t('第','Question ')}${q.index+1} / ${lifestyle.questions.length}">${lifestyle.questions.map((_,i)=>`<span class="${i<=q.index?'complete':''}"></span>`).join('')}</div><p class="life-section-label">${pair([['01 · 平时怎么开始','01 · Getting started'],['02 · 怎样更容易坚持','02 · Keeping going'],['03 · 安排适合你的日常','03 · Your preferences']][Math.floor(q.index/4)])}</p><p class="eyebrow">${String(q.index+1).padStart(2,'0')} / ${lifestyle.questions.length}</p><h1 id="life-question-title">${pair(question.title)}</h1><p class="life-hint">${pair(question.hint)}</p><div class="life-options" role="group" aria-labelledby="life-question-title">${question.options.map((o,i)=>`<button class="life-option" data-life-answer="${o.id}" aria-pressed="${selected===o.id}"><span aria-hidden="true">${selected===o.id?'✓':String.fromCharCode(65+i)}</span><span>${pair(o.label)}</span></button>`).join('')}</div><div class="life-question-actions"><button class="text-link" data-life="previous">← ${q.index?t('上一题','Previous'):t('返回介绍','Introduction')}</button><button class="primary" data-life="next" ${!selected?'disabled':''}>${q.index===lifestyle.questions.length-1?t('看看我的考拉','Meet my Kora'):t('下一题','Next')} ${icon('arrow')}</button></div></div></div></section>`;
}
function lifeHome(){const r=state.profile.lifestyle;if(!lifestyle.valid(r))return `<section class="life-home"><div>${lifeArt('busy')}</div><div><h2>${t('找到更适合你的节奏','Find a rhythm that fits')}</h2><p>${t('12 道日常小问题，了解你的习惯和偏好。','12 everyday questions about your habits and preferences.')}</p><button class="text-link" data-life="open">${t('试试趣味测试','Try the quiz')} ↗</button></div></section>`;return `<section class="life-home">${r.balanced?portrait('calm'):lifeArt(r.type)}<div><p class="eyebrow">${t('我的生活偏好','MY STYLE')}</p><h2>${lifeName(r)}</h2><p>${lifeCare(r)}</p><button class="text-link" data-route="profile">${t('查看结果与偏好','My result & preferences')} ↗</button></div></section>`;}
function lifeProfile(){const r=state.profile.lifestyle;if(!lifestyle.valid(r))return lifeHome();const current={...r,activities:state.profile.activities,minutes:state.profile.minutes,preferredTime:state.profile.preferredTime,reminderPreference:state.profile.reminderPreference};return `<section class="life-profile" style="${lifeStyle(r.type)}">${r.balanced?portrait('calm'):lifeArt(r.type)}<div><p class="eyebrow">${t('你的生活偏好 · 搭子的语气可以另外选','YOUR STYLE · CHOOSE KORA’S VOICE SEPARATELY')}</p><h2>${lifeName(r)}</h2><p>“${lifeQuote(r)}”</p>${lifeFacts(current)}${lifeEvidence(r)}<div class="life-actions"><button class="text-link" data-life="open">${t('重新测试','Retake quiz')} ↗</button><button class="text-link" data-life="download-saved">${t('保存结果卡片','Save result card')} ↓</button></div><p class="helper">${t('运动、时长、时段和提醒偏好都可以在下方直接修改。已有计划不会自动变化。','Edit activity, duration, timing and reminder preferences below. Existing plans stay unchanged.')}</p><p id="life-export-status" role="status"></p></div></section>`;}
function showLifePlan(){
 if(!lifePlanDraft)return;
 openModal(modalShell(`<h2 id="modal-title">${t('让今天更像你的节奏。','Let today move at your pace.')}</h2><p class="modal-sub">${t('这是根据你的生活偏好生成的起步建议，可以不采用。','A starting suggestion based on your preferences. You can keep your current plan.')}</p><div class="life-review"><small>${t('目前的安排','Current plan')}</small><strong>${planTitle()}</strong></div><div class="life-review"><small>${t('确认后，今天改为','After you confirm')}</small><strong>${planTitle(lifePlanDraft.plan)}</strong></div><p>${t('只调整尚未完成的训练。餐食与历史记录保留；可以撤销。','Adjusts only unfinished training. Food and history stay; you can undo.')}</p>${reservationChoice(lifePlanDraft)}<div class="modal-actions"><button class="text-link" data-action="close">${t('保留原计划','Keep my plan')}</button><button class="primary" data-life="confirm-plan">${t('采用这个安排','Use this suggestion')} ${icon('check')}</button></div>`,t('人格推荐 · 你来确认','YOUR STYLE · YOUR CHOICE')),'life-plan');
}
async function downloadLifeCard(r){
 if(!lifestyle.valid(r))return;
 const en=state.language==='en',d=lifestyle.types[r.type],msg=document.getElementById('life-export-status');
 try{
  if(msg)msg.textContent=t('正在制作卡片……','Making your card…');
  const img=new Image();img.src=r.balanced?'assets/kora-calm-sport-v2.png':`assets/kora-life-${r.type}-v4.png`;await img.decode();
  const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');
  ctx.fillStyle=d.soft;ctx.fillRect(0,0,1080,1350);ctx.fillStyle=d.color;
  ctx.font='600 34px sans-serif';ctx.fillText('kora. / THE EVERYDAY YOU',70,90);
  ctx.drawImage(img,140,145,800,800);ctx.textAlign='center';ctx.font='600 68px sans-serif';ctx.fillText(lifeName(r),540,1020,940);ctx.font='24px sans-serif';ctx.fillText(r.balanced?'YOUR RHYTHM':d.code+' · '+d.tag[en?1:0],540,1080);
  ctx.font='28px sans-serif';const words=en?lifeQuote(r).split(' '):[...lifeQuote(r)];let line='',y=1160;for(const word of words){const next=line+(en&&line?' ':'')+word;if(ctx.measureText(next).width>900){ctx.fillText(line,540,y);y+=42;line=word;}else line=next;}ctx.fillText(line,540,y);
  ctx.font='20px sans-serif';ctx.fillText(en?'A playful preference. You can change.':'趣味生活偏好 · 你可以有很多种样子',540,1295);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('export');
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Kora-${d.code}-${en?'en':'zh'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  if(msg)msg.textContent=en?'Card ready. Check your browser downloads.':'卡片已生成，请查看浏览器下载。';
 }catch{if(msg)msg.textContent=t('暂时无法生成卡片，请重试。','Could not create the card. Please try again.');}
}
function handleLifeClick(b){
 if(b.dataset.lifeAnswer&&quizSession?.phase==='questions'){
  const answer=b.dataset.lifeAnswer;if(!lifestyle.questions[quizSession.index].options.some(o=>o.id===answer))return true;
  quizSession.answers[quizSession.index]=answer;saveQuizDraft();render();document.querySelector(`[data-life-answer="${answer}"]`)?.focus({preventScroll:true});return true;
 }
 const action=b.dataset.life;if(!action)return false;
 if(action==='open'){beginQuiz();return true;}
 if(action==='exit'){quizSession=null;saveQuizDraft();render();return true;}
 if(action==='start'||action==='restart'){quizSession={version:2,phase:'questions',index:0,answers:[]};quizRender();return true;}
 if(action==='download'||action==='download-saved'){downloadLifeCard(action==='download'?lifestyle.result(quizSession?.answers):state.profile.lifestyle);return true;}
 if(action==='previous'&&quizSession){if(quizSession.index===0)quizSession.phase='intro';else quizSession.index--;quizRender();return true;}
 if(action==='next'&&quizSession){if(!quizSession.answers[quizSession.index])return true;if(quizSession.index===lifestyle.questions.length-1){if(!lifestyle.result(quizSession.answers))return true;quizSession.phase='result';}else quizSession.index++;quizRender();return true;}
 if(action==='accept'&&quizSession){
  const r=lifestyle.result(quizSession.answers);if(!r)return true;
  if(state.onboarded){state.profile=lifestyle.apply(state.profile,r);if(profileDraft)profileDraft=lifestyle.apply(profileDraft,r);}else{setupDraft=lifestyle.apply(setupDraft,r);state.profile=structuredClone(setupDraft);}
  quizSession=null;saveQuizDraft();const saved=save();render();window.scrollTo(0,0);
  if(state.onboarded)toast(saved?t('人格与偏好已同步。现有计划保留，新建议由你确认。','Type and preferences synced. Your current plan stays until you choose.'):t('暂时无法保存，只在本次页面保留。','Could not save. Session only.'));return true;
 }
 if(action==='plan'&&state.onboarded){const rec=lifestyle.recommendation(state.profile);if(!rec||rec.checkIn||state.plan.done||todayCare()?.done||state.plan.type==='rest')return true;lifePlanDraft={plan:rec.plan,date:state.date,base:JSON.stringify(state.plan)};showLifePlan();return true;}
 if(action==='confirm-plan'&&lifePlanDraft){
  const d=lifePlanDraft;if(d.date!==state.date||d.base!==JSON.stringify(state.plan)||!calendar.adjust(state,d.plan,'lifestyle',new Date().toISOString(),planChangeOptions(d))){closeModal();toast(t('安排已经变化，请重新查看建议。','Your plan changed. Please review the suggestion again.'));return true;}
  // Keep the existing completion/undo journey available for this confirmed suggestion.
  state.days[state.date].comeback={energy:'ready',reason:'routine',action:d.plan.action,done:false,at:new Date().toISOString()};
  closeModal();render();persistNotice(t('今天的安排已更新，可以随时撤销。','Today’s plan is updated. You can undo it.'));return true;
 }
 return true;
}
document.addEventListener('click',event=>{
 if(refreshDate())return;
 const b=event.target.closest('button,[data-route]');if(!b)return;
 if(b.dataset.action==='dismiss-cheer'){hideCheer();$('#main').focus({preventScroll:true});return;}
 if(b.dataset.lang){setLanguage(b.dataset.lang);return;}
 if(handleLifeClick(b))return;
 if(b.dataset.action==='about'){showAbout();return;}if(b.dataset.action==='close'){closeModal();return;}
 if(b.dataset.persona){captureForm();if(!state.onboarded)setupDraft.persona=b.dataset.persona;else{profileDraft=profileDraft||structuredClone(state.profile);profileDraft.persona=b.dataset.persona;}render();return;}
 if(b.dataset.action==='setup-next'&&!state.onboarded&&PERSONA_IDS.includes(setupDraft.persona)){setupStep=2;render();window.scrollTo(0,0);$('#profile-name').focus();return;}
 if(b.dataset.action==='setup-back'&&!state.onboarded){captureForm();setupStep=1;render();window.scrollTo(0,0);return;}
 if(!state.onboarded)return;
 if(b.dataset.energy){if(b.dataset.energy==='low'){startIssue('time');}else startComeback(b.dataset.energy);return;}
 if(b.dataset.comebackReason&&comebackDraft){comebackDraft.reason=b.dataset.comebackReason;showComebackReason();return;}
 if(b.dataset.comebackAction&&comebackDraft){comebackDraft.action=b.dataset.comebackAction;showComebackReview();return;}
 if(b.dataset.scene!==undefined){captureForm();const scene=Number(b.dataset.scene);if(Number.isInteger(scene)&&rewards.owns(state,['trail','creek','stars'][scene])){state.profile.scene=scene;if(profileDraft)profileDraft.scene=scene;render();showRewards();persistNotice(t('背景已换好。','Your background is set.'));}return;}
 if(b.dataset.shopTab){shopTab=b.dataset.shopTab;shopPreview=null;showRewards();return;}
 if(b.hasAttribute('data-shop-back')){shopPreview=null;showRewards();return;}
 if(b.dataset.previewReward){shopPreview=b.dataset.previewReward;showRewards();return;}
 if(b.dataset.buy){b.disabled=true;if(rewards.buy(state,b.dataset.buy)){if(b.dataset.buy==='bird')state.wallet.bird=true;else{state.profile.scene=rewards.items.find(i=>i.id===b.dataset.buy).scene;if(profileDraft)profileDraft.scene=state.profile.scene;}shopPreview=null;shopTab='collection';render();showRewards();persistNotice(t('兑换好啦，已经为你布置上了。','Collected! Your new reward is in place.'));}else{shopPreview=null;showRewards();toast(t('余额或收藏已变化，请重新查看。','Your balance or collection changed. Please check again.'));}return;}
 if(b.hasAttribute('data-toggle-bird')){if(rewards.owns(state,'bird')){state.wallet.bird=!state.wallet.bird;render();showRewards();persistNotice(t('小鸟的布置已更新。','Your bird setting is saved.'));}return;}
 if(b.dataset.weekDate){showWeekDay(b.dataset.weekDate);return;}
 if(b.dataset.reportKind){reportKind=b.dataset.reportKind;reportOffset=0;showReport();return;}if(b.dataset.reportOffset){reportOffset=Math.min(0,reportOffset+Number(b.dataset.reportOffset));showReport();return;}
 if(b.dataset.week){weekOffset+=Number(b.dataset.week);if(modalView==='records')showRecords();else render();return;}if(b.dataset.historyDate){showHistory(b.dataset.historyDate);return;}
 if(b.dataset.route){if(quizSession){quizSession=null;saveQuizDraft();}route(b.dataset.route);return;}if(b.dataset.issue){startIssue(b.dataset.issue);return;}if(b.dataset.choice&&draft){draft.choice=b.dataset.choice;showConfirm();return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.prompt){sendChat(pair(issueLabels[b.dataset.prompt]));return;}
 if(b.dataset.deleteLog){state.logs=state.logs.filter(l=>l.id!==b.dataset.deleteLog);render();persistNotice(t('已删除这条餐食记录。','Meal entry deleted.'));return;}
 if(b.dataset.workout){if(state.plan.done||todayCare()?.done){toast(t('已完成的行动不会被替换。','Completed activities will not be replaced.'));return;}draft={workout:b.dataset.workout,date:state.date,base:JSON.stringify(state.plan)};showConfirm();return;}
 if(b.dataset.recipe!==undefined){showRecipe(Number(b.dataset.recipe));return;}
 switch(b.dataset.action){
 case 'coach-interact':interactCoach();break;
 case 'toggle-coach-motion':captureForm();state.profile.motionPaused=!state.profile.motionPaused;if(profileDraft)profileDraft.motionPaused=state.profile.motionPaused;render();persistNotice(state.profile.motionPaused?t('Kora 会安静陪着你，点击仍可聊天。','Kora will stay still and still respond to taps.'):t('陪伴动作已开启。','Companion motion is on.'));break;
 case 'focus-today':if($('#modal').open)closeModal();focusTodayNode();break;
 case 'next-path-week':pathWeekOffset=1;render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'today-plan':showTodayPlan();break;
 case 'adjust-reason':showAdjustReason();break;
 case 'not-well':if(state.plan.session?.running){calendar.pause(state);save();render();}showNotWell();break;
 case 'record-hub':showRecordHub();break;
 case 'open-month':reportKind='month';reportOffset=0;showReport();break;
 case 'records':weekOffset=0;showRecords();break;
 case 'leaf-shop':shopTab='browse';shopPreview=null;showRewards();break;
 case 'trail-reward':shopTab='collection';shopPreview=null;showRewards();break;
 case 'rest-checkin':showRestCheckin();break;
 case 'undo-rest-checkin':delete state.days[state.date].restCheckin;render();showTodayPlan();persistNotice(t('回顾已撤销，叶子也已重新核对。','Check-in removed; your leaves have been recalculated.'));break;
 case 'open-report':reportKind='week';reportOffset=0;showReport();break;
 case 'report':showReport();break;
 case 'schedule-review':scheduleForm=null;showSchedule();break;
 case 'schedule-edit':showSchedule();break;
 case 'schedule-preview':previewSchedule();break;
 case 'schedule-confirm':b.disabled=true;confirmSchedule();break;
 case 'cancel-reservation':if(journey.cancelScheduled(state,b.dataset.date)){render();showHistory(b.dataset.date);persistNotice(t('这一天的预约已取消，其他记录保留。','Reservation cancelled. Other records are kept.'));}break;
 case 'trail-next':showTodayPlan();break;
 case 'comeback-energy':showComebackEnergy();break;
 case 'comeback-review':if(comebackDraft)showComebackReview();break;
 case 'comeback-back':if(comebackDraft){if(comebackDraft.energy==='ready'||comebackDraft.energy==='rest')showComebackReview();else showComebackReason();}break;
 case 'comeback-confirm':b.disabled=true;confirmComeback();break;
 case 'comeback-complete':if(comeback.complete(state)){render();if(state.plan.type==='rest')persistNotice(returnMessage());else celebrate('training');}break;
 case 'back-options':draft?.workout?closeModal():showChoices();break;
 case 'confirm-plan':b.disabled=true;commitDraft();break;
 case 'back-today':closeModal();route('today');break;
 case 'go-chat':closeModal();route('chat');break;
 case 'meal-done':state.mealDone=!state.mealDone;render();persistNotice(state.mealDone?say('done'):t('已取消完成标记。','Completion mark removed.'));break;
 case 'training-done':showComplete();break;
 case 'start-session':if(calendar.start(state)){save();render();showSession();}break;
 case 'show-session':showSession();break;
 case 'pause-session':calendar.pause(state);save();render();showSession();break;
 case 'complete-session':if(calendar.complete(state)){closeModal();render();celebrate('training');}break;
 case 'uncomplete-session':calendar.uncomplete(state);closeModal();render();persistNotice(t('已撤销完成标记，没有开启提醒。','Completion mark removed. Notifications remain off.'));break;
 case 'resume-plan':draft={choice:'resume',issue:'resume',date:state.date,base:JSON.stringify(state.plan)};showConfirm();break;
 case 'undo':if(calendar.undo(state)){render();if($('#modal').open)showTodayPlan();persistNotice(t('已恢复上一次安排和改期日期。','Previous plan and reservation restored.'));}else toast(t('目标日期已有新记录，无法撤销。','The target date has new records; undo is unavailable.'));break;
 case 'legacy':showLegacy();break;
 case 'this-week':weekOffset=0;if(modalView==='records')showRecords();else render();break;
 case 'reset':showReset();break;
 case 'confirm-reset':{const language=state.language;try{localStorage.removeItem(STORAGE_KEY);}catch{toast(t('未能清除浏览器数据，请在浏览器设置中清除。','Could not clear saved data. Please use browser settings.'));return;}state=freshState();state.language=language;quizSession=null;saveQuizDraft();setupStep=1;setupDraft=structuredClone(state.profile);profileDraft=null;chats.length=0;filter='all';closeModal();render();window.scrollTo(0,0);break;}
 }
});
function updateEstimate(){const f=foods.find(f=>f.id===$('#food-name').value),grams=Number($('#food-grams').value);$('#food-estimate').textContent=Number.isFinite(grams)&&grams>0&&grams<=2000?Math.round(f.cal*grams/100):'—';}
document.addEventListener('input',e=>{if(['food-name','food-grams'].includes(e.target.id))updateEstimate();});
document.addEventListener('change',e=>{if(modalView==='schedule'&&scheduleForm){scheduleForm.dates=Array.from(document.querySelectorAll('[data-schedule-date]:checked:not(:disabled)')).map(el=>el.dataset.scheduleDate);scheduleForm.minutes=Number($('#schedule-minutes').value);scheduleForm.activity=$('#schedule-activity').value;}if(e.target.id==='food-name')updateEstimate();if(e.target.dataset.reservation){const d=modalView==='life-plan'?lifePlanDraft:modalView==='comeback-review'?comebackDraft:draft;if(d){d.cancelReservation=e.target.dataset.reservation==='cancel';refreshModal();}}});
document.addEventListener('submit',event=>{
 event.preventDefault();if(refreshDate())return;const id=event.target.id;
 if(id==='setup-form'||id==='profile-form'){
  const p=readProfileForm(id==='setup-form'?setupDraft:(profileDraft||state.profile));const error=profileError(p);if(error){$('#form-error').textContent=error;$('#form-error').setAttribute('tabindex','-1');$('#form-error').focus();return;}
  state.profile=p;const first=id==='setup-form';if(first)state.plan=calendar.defaultPlan(state);state.onboarded=true;profileDraft=null;setupDraft=structuredClone(p);const saved=save();if(first){location.hash='today';currentRoute='today';lastAnimatedRoute=null;}render();window.scrollTo(0,0);toast(saved?(first?t('资料已同步到档案。欢迎和 Kora 一起开始。','Your details are in Profile. Welcome to life with Kora.'):t('档案已保存，性格已同步。现有计划不变。','Profile and personality saved. Your existing plan is unchanged.')):t('浏览器未能保存，当前资料仅在本次页面保留。','Could not save. Your details last only for this session.'));return;
 }
 if(!state.onboarded)return;
 if(id==='rest-checkin-form'){const mood=$('#rest-mood').value;if(state.plan.type!=='rest'||!['tired','okay','sore'].includes(mood))return;state.days[state.date].restCheckin={mood};render();showTodayPlan();persistNotice(leafGain?t('今天的状态记下啦，收好这片叶子。+1 🍃','Check-in saved. A little leaf for taking care of you. +1 🍃'):t('今天的状态已更新。','Your check-in is updated.'));return;}
 if(id==='food-form'){const f=foods.find(f=>f.id===$('#food-name').value),grams=Number($('#food-grams').value);if(!Number.isFinite(grams)||grams<1||grams>2000){toast(t('请输入1—2000克之间的实际份量。','Enter a portion from 1 to 2000 grams.'));return;}state.logs.push({date:state.date,at:new Date().toISOString(),id:String(Date.now())+String(Math.random()).slice(2,6),foodId:f.id,grams,cal:Math.round(f.cal*grams/100)});render();celebrate('meal');}
 if(id==='chat-form')sendChat($('#chat-text').value);
});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(quizSession&&state.onboarded){quizSession=null;saveQuizDraft();}if(currentRoute!==location.hash.slice(1))profileDraft=null;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
window.addEventListener('focus',refreshDate);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDate();});
setInterval(refreshDate,30000);
setInterval(()=>{document.querySelectorAll('[data-session-clock]').forEach(node=>node.textContent=sessionTime());},1000);
window.addEventListener('pagehide',()=>{companionDispose?.();motion?.revert();});
render();

if(!state.onboarded)window.scrollTo(0,0);
